-- ---------------------------------------------------------------------------
-- The last of this deployment's taste, out of the code and into its row.
--
-- 014 moved the niches, the personas and the scoring brief. This moves the rest:
-- which OpenStreetMap tags belong to which category, the name filter that keeps
-- dry cleaners out of a search for makers, the rule that a business with no
-- website needs an Instagram before it counts as a lead, the bootstrap search
-- terms, and the Wikipedia pages the vocabulary is mined from.
--
-- All three were hand-tuned by one person for one kind of business, and none of
-- them generalise — a clinic with a phone and no website is exactly the lead
-- that rule would have thrown away. So they belong to a profile, not to the
-- code, and the code now ships with none of them.
--
-- Nothing changes for this deployment: osmSpecFor() reads these fields in
-- preference to any default, so it will find exactly what it found yesterday.
--
-- Safe to re-run.
--   pnpm exec wrangler d1 execute lead-finder --remote --file=./migrations/015_discovery_to_data.sql
-- ---------------------------------------------------------------------------

UPDATE profiles SET
  niches    = '{"alt_fashion": {"label": "Alternative fashion", "keywords": ["emo", "goth", "gothic", "nu goth", "pastel goth", "punk", "grunge", "metalcore", "scene", "alt fashion", "alternative clothing", "alternative fashion", "subculture", "occult", "witchy", "cutecore", "cute", "kawaii", "pastel", "coquette", "fairycore", "dollette", "babycore", "sanrio", "plushie", "bows", "ribbon", "harajuku", "lolita", "gothic lolita", "sweet lolita", "classic lolita", "jirai kei", "visual kei", "fairy kei", "mori kei", "dolly kei", "yami kawaii", "menhera", "gyaru", "decora", "shironuri", "jfashion", "japanese street", "japanese inspired", "tokyo", "kimono", "yukata", "y2k", "90s", "vintage", "thrifted", "deadstock", "upcycled", "reworked", "streetwear", "corset", "platform boots", "handmade clothing"], "osm": {"amenity": [], "healthcare": [], "craft": [], "shop": ["antiques", "second_hand", "boutique", "bag", "clothes"], "office": []}}, "craft_goods": {"label": "Handmade & craft goods", "keywords": ["handmade", "ceramic", "ceramics", "pottery", "jewelry", "jewellery", "stationery", "enamel pin", "sticker", "zine", "print shop", "art object", "woodwork", "textile", "weaving", "candle", "artisan"], "osm": {"amenity": [], "healthcare": [], "craft": ["potter", "jeweller", "goldsmith", "basket_maker", "bookbinder", "candlemaker", "glassblower", "leather", "weaver"], "shop": ["pottery", "craft", "jewelry", "candles"], "office": []}}, "beauty_wellness": {"label": "Beauty & skincare", "keywords": ["skincare", "skin care", "serum", "cleanser", "moisturizer", "beauty", "cosmetics", "fragrance", "perfume", "balm", "apothecary", "wellness"], "osm": {"amenity": [], "healthcare": [], "craft": [], "shop": ["cosmetics", "perfumery", "herbalist"], "office": []}}, "food_bev": {"label": "Food & beverage", "keywords": ["coffee", "roaster", "tea", "chocolate", "bakery", "hot sauce", "condiment", "snack", "granola", "kombucha", "brewery", "distillery", "small batch", "provisions", "pantry"], "o