  discovery = '{"social": true, "exclude_names": "\\b(?:cleaners?|dry\\s*clean|laundr|alterations?|tailor(?:ing|s)?|shoe\\s*repair|cobbler|locksmith|barber|nail\\s*salon|pharmacy|deli|bodega|smoke\\s*shop|check\\s*cashing|wireless|mobile\\s*repair)\\b", "source_keywords": {"alt_fashion": ["lolita", "emo", "kawaii", "harajuku", "decora", "goth"], "craft_goods": ["letterpress", "macrame", "printmaker", "ceramicist"], "beauty_wellness": ["apothecary", "botanica"], "food_bev": ["roastery", "chocolatier"], "artist_portfolio": ["atelier", "linocut"], "creative_studio": ["designstudio"], "lifestyle_brand": ["mercantile", "sundries"]}, "wiki_sources": [{"kind": "category", "title": "Fashion aesthetics", "niche": "alt_fashion"}, {"kind": "category", "title": "Punk fashion", "niche": "alt_fashion"}, {"kind": "category", "title": "Gothic fashion", "niche": "alt_fashion"}, {"kind": "category", "title": "Subcultures by type", "niche": "alt_fashion"}, {"kind": "category", "title": "Japanese street fashion", "niche": "alt_fashion"}, {"kind": "category", "title": "Japanese fashion", "niche": "alt_fashion"}, {"kind": "links", "title": "Japanese street fashion", "niche": "alt_fashion"}, {"kind": "category", "title": "Dresses", "niche": "alt_fashion"}, {"kind": "category", "title": "Skirts", "niche": "alt_fashion"}, {"kind": "category", "title": "Boots", "niche": "alt_fashion"}, {"kind": "category", "title": "Studio pottery", "niche": "craft_goods"}, {"kind": "category", "title": "Handicrafts", "niche": "craft_goods"}, {"kind": "category", "title": "Jewellery", "niche": "craft_goods"}, {"kind": "category", "title": "Printmaking", "niche": "artist_portfolio"}, {"kind": "category", "title": "Cosmetics", "niche": "beauty_wellness"}]}',
